        return (high[0] - low[0], high[1] - low[1], high[2] - low[2])

    def to_dict(self) -> dict[str, object]:
        return {
            "root": self.root,
            "links": len(self.links),
            "joints": len(self.joints),
            "mass_kg": round(self.total_mass_kg, 4),
