    mission: Mission,
    *,
    world: WorldSection,
    agents: Sequence[AgentSection],
) -> bool:
    """Миссию можно запускать, если среди замечаний нет ошибок."""
    return not any(
        item.severity is Severity.ERROR
        for item in mission_issues(mission, world=world, agents=agents, prefix="mission")
    )


