def _cycle_nodes(graph: MissionGraph) -> set[str]:
    """Элементы, лежащие на цикле."""
    state: dict[str, int] = {}
    nodes: set[str] = set()

    def visit(node_id: str, path: list[str]) -> None:
        state[node_id] = 1
        path.append(node_id)
        for target in graph.successors.get(node_id, ()):
            if state.get(target) == 1:
                if target in path:
                    nodes.update(path[path.index(target) :])
            elif state.get(target, 0) == 0:
                visit(target, path)
        path.pop()
        state[node_id] = 2

    for element in graph.elements:
        if state.get(element.id, 0) == 0:
            visit(element.id, [])
